record:
{% include "apis/OAI_preprint_record_header.xml" with article=article %}


{% with file=article.current_version.file %}
  {# Free to read now, or from a known embargo end. A restricted file, or an embargo with no end, isn't. #}
  {% if file and file.access == "embargoed" and file.embargo_until %}

  {% elif file and not file.is_locked %}

  {% endif %}
  {% if article.license %}
  {{ article.license.url }}
  {% endif %}
  {% if article.abstract %}
  {{ article.abstract|striptags }}
  {% endif %}
  {# A locked file's URL is never published; the record page stands in. #}
  {% if file and not file.is_locked %}
  {{ file.mime_type }}
  {{ article.repository.site_url }}{{ file.download_url }}
  {% else %}
  {{ article.url }}
  {% endif %}
  {{ article.rioxx_language }}
  {% with publisher=article.rioxx_publisher %}{% if publisher %}
  {{ publisher }}
  {% endif %}{% endwith %}
  {% if article.doi %}
  https://doi.org/{{ article.doi }}
  {% endif %}
  {% for s in article.subject.all %}
  {{ s.name }}
  {% endfor %}
  {% for k in article.keywords.all %}
  {{ k.word }}
  {% endfor %}
  {{ article.title|striptags }}
  {% for author in article.frozen_authors %}
  {{ author.dc_name_string }}
  {% endfor %}
  {% if article.date_published %}
  {{ article.date_published|date:"Y-m-d" }}
  {{ article.date_published|date:"Y-m-d" }}
  {% endif %}
  {{ article.coar_type }}
  {% if file %}{{ file.jav_version }}{% else %}NA{% endif %}
{% endwith %}
